19	// resolveTranscriptPath determines the correct file path for an agent's session transcript.
20	// Computes the path dynamically from the current repo location for cross-machine portability.
21	func resolveTranscriptPath(ctx context.Context, sessionID string, agent agentpkg.Agent) (string, error) {
22		repoRoot, err := paths.WorktreeRoot(ctx)
23		if err != nil {
24			return "", fmt.Errorf("failed to get worktree root: %w", err)
25		}
26	
27		sessionDir, err := agent.GetSessionDir(repoRoot)
28		if err != nil {
29			return "", fmt.Errorf("failed to get agent session directory: %w", err)
30		}
31		return agent.ResolveSessionFile(sessionDir, sessionID), nil
32	}
33	
34	// searchTranscriptInProjectDirs searches for a session transcript across an agent's
35	// project directories that could plausibly belong to the current repository.
36	// Agents like Claude Code and Gemini CLI derive the project directory from the cwd,
37	// so the transcript may be stored under a different project directory if the session
38	// was started from a different working directory.
39	//
40	// The search is scoped to the agent's base directory (e.g., ~/.claude/projects) and only
41	// walks immediate subdirectories (plus one extra level for agents like Gemini that nest
42	// chats under <project>/chats/).
43	// Only agents implementing SessionBaseDirProvider support this fallback search.
44	func searchTranscriptInProjectDirs(sessionID string, ag agentpkg.Agent) (string, error) {
45		provider, ok := agentpkg.AsSessionBaseDirProvider(ag)
46		if !ok {
47			return "", fmt.Errorf("fallback transcript search not supported for agent %q", ag.Name())
48		}
49		baseDir, err := provider.GetSessionBaseDir()
50		if err != nil {
51			return "", fmt.Errorf("failed to get base directory: %w", err)
52		}
53	
54		// Walk subdirectories with a max depth of 3 (baseDir/project/subdir/file)
55		// to avoid scanning unrelated project trees.
56		const maxExtraDepth = 3
57	
58		var found string
59		walkErr := filepath.WalkDir(baseDir, func(path string, d os.DirEntry, err error) error {
60			if err != nil {
61				return nil //nolint:nilerr // skip inaccessible dirs
62			}
63			if !d.IsDir() {
64				return nil
65			}
66			// Limit walk depth using relative path from base
67			rel, relErr := filepath.Rel(baseDir, path)
68			if relErr != nil {
69				return filepath.SkipDir
70			}
71			depth := strings.Count(rel, string(filepath.Separator))
72			if depth > maxExtraDepth {
73				return filepath.SkipDir
74			}
75			candidate := ag.ResolveSessionFile(path, sessionID)
76			if _, statErr := os.Stat(candidate); statErr == nil {
77				found = candidate
78				return filepath.SkipAll
79			}
80			return nil
81		})
82		if walkErr != nil {
83			return "", fmt.Errorf("failed to search project directories: %w", walkErr)
84		}
85		if found != "" {
86			return found, nil
87		}
88		return "", errors.New("transcript not found in any project directory")
89	}
90	
91	// AgentTranscriptPath returns the path to a subagent's transcript file.
92	// Subagent transcripts are stored as agent-{agentId}.jsonl in the same directory
93	// as the main transcript.
94	func AgentTranscriptPath(transcriptDir, agentID string) string {
95		return filepath.Join(transcriptDir, fmt.Sprintf("agent-%s.jsonl", agentID))
96	}
97	
98	// toolResultBlock represents a tool_result in a user message
99	type toolResultBlock struct {
100		Type      string `json:"type"`
101		ToolUseID string `json:"tool_use_id"`
102	}
103	
104	// userMessageWithToolResults represents a user message that may contain tool results
105	type userMessageWithToolResults struct {
106		Content []toolResultBlock `json:"content"`
107	}
108	
109	// FindCheckpointUUID finds the UUID of the message containing the tool_result
110	// for the given tool_use_id. This is used to find the checkpoint point for
111	// transcript truncation when rewinding to a task.
112	// Returns the UUID and true if found, empty string and false otherwise.
113	func FindCheckpointUUID(lines []transcriptLine, toolUseID string) (string, bool) {
114		for _, line := range lines {
115			if line.Type != transcript.TypeUser {
116				continue
117			}
118	
119			var msg userMessageWithToolResults
120			if err := json.Unmarshal(line.Message, &msg); err != nil {
121				continue
122			}
123	
124			for _, block := range msg.Content {
125				if block.Type == "tool_result" && block.ToolUseID == toolUseID {
126					return line.UUID, true
127				}
128			}
129		}
130		return "", false
131	}
132	
133	// TruncateTranscriptAtUUID returns transcript lines up to and including the
134	// line with the given UUID. If the UUID is not found or is empty, returns
135	// the entire transcript.
136	//
137	//nolint:revive // Exported for testing purposes
138	func TruncateTranscriptAtUUID(lines []transcriptLine, uuid string) []transcriptLine {
139		if uuid == "" {
140			return lines
141		}
142	
143		for i, line := range lines {
144			if line.UUID == uuid {
145				return lines[:i+1]
146			}
147		}
148	
149		// UUID not found, return full transcript
150		return lines
151	}
152	
153	// writeTranscript writes transcript lines to a file in JSONL format.
154	func writeTranscript(path string, lines []transcriptLine) error {
155		file, err := os.Create(path) //nolint:gosec // Writing to controlled git metadata path
156		if err != nil {
157			return fmt.Errorf("failed to create file: %w", err)
158		}
159		defer func() { _ = file.Close() }()
160	
161		for _, line := range lines {
162			data, err := json.Marshal(line)
163			if err != nil {
164				return fmt.Errorf("failed to marshal line: %w", err)
165			}
166			if _, err := file.Write(data); err != nil {
167				return fmt.Errorf("failed to write line: %w", err)
168			}
169			if _, err := file.WriteString("\n"); err != nil {
170				return fmt.Errorf("failed to write newline: %w", err)
171			}
172		}
173	
174		return nil
175	}
176	
177	// TranscriptPosition contains the position information for a transcript file.
178	type TranscriptPosition struct {
179		LastUUID  string // Last non-empty UUID (from user/assistant messages)
180		LineCount int    // Total number of lines
181	}
182	
183	// GetTranscriptPosition reads a transcript file and returns the last UUID and line count.
184	// Returns empty position if file doesn't exist or is empty.
185	// Only considers UUIDs from actual messages (user/assistant), not summary rows which use leafUuid.
186	func GetTranscriptPosition(path string) (TranscriptPosition, error) {
187		if path == "" {
188			return TranscriptPosition{}, nil
189		}
190	
191		file, err := os.Open(path) //nolint:gosec // Reading from controlled transcript path
192		if err != nil {
193			if os.IsNotExist(err) {
194				return TranscriptPosition{}, nil
195			}
196			return TranscriptPosition{}, fmt.Errorf("failed to open transcript: %w", err)
197		}
198		defer func() { _ = file.Close() }()
199	
200		var pos TranscriptPosition
201		reader := bufio.NewReader(file)
202	
203		for {
204			lineBytes, err := reader.ReadBytes('\n')
205			if err != nil && err != io.EOF {
206				return TranscriptPosition{}, fmt.Errorf("failed to read transcript: %w", err)
207			}
208	
209			if len(lineBytes) == 0 {
210				if err == io.EOF {
211					break
212				}
213				continue
214			}
215	
216			pos.LineCount++
217	
218			// Parse line to extract UUID (only from user/assistant messages, not summaries)
219			var line transcriptLine
220			if err := json.Unmarshal(lineBytes, &line); err == nil {
221				if line.UUID != "" {
222					pos.LastUUID = line.UUID
223				}
224			}
225	
226			if err == io.EOF {
227				break
228			}
229		}
230	
231		return pos, nil
232	}
