		{Type: "assistant", UUID: "a3", Message: []byte(`{"content":[{"type":"tool_use","id":"toolu_task2","name":"Task","input":{}}]}`)},
		{Type: "user", UUID: "u3", Message: []byte(`{"content":[{"type":"tool_result","tool_use_id":"toolu_task2","content":"Second task done"}]}`)},
