		{Type: "assistant", UUID: "a1", Message: []byte(`{"content":[]}`)},
		{Type: "user", UUID: "u2", Message: []byte(`{"content":"Second"}`)},
		{Type: "assistant", UUID: "a2", Message: []byte(`{"content":[]}`)},
		{Type: "user", UUID: "u3", Message: []byte(`{"content":"Third"}`)},
	}

	tests := []struct {
		name         string
		uuid         string
		expectedLen  int
		expectedLast string
	}{
		{
			name:         "truncate at u2",
			uuid:         "u2",
			expectedLen:  3,
			expectedLast: "u2",
		},
		{
			name:         "truncate at first",
			uuid:         "u1",
			expectedLen:  1,
			expectedLast: "u1",
