func TestGetTranscriptPosition_MixedWithMalformedLines(t *testing.T) {
	content := `{"type":"user","uuid":"user-1","message":{"content":"Hello"}}
not valid json
{"type":"assistant","uuid":"asst-1","message":{"content":[{"type":"text","text":"Hi"}]}}
{broken json
