253	// StoreAgentTypeHint records the agent type that owns a session before
254	// SessionState exists. Used by the lifecycle dispatcher when SessionStart fires
255	// (state isn't created until TurnStart, so we need a place to remember which
256	// agent claimed the session first).
257	//
258	// Semantics: first writer wins. When multiple agents fire hooks for the same
259	// session ID — e.g., Cursor IDE running cursor-agent while also forwarding to
260	// Claude Code's hook system — only the agent that fires SessionStart first
261	// gets recorded. Subsequent calls return nil without overwriting.
262	//
263	// At TurnStart, InitializeSession reads this hint to override agentType when
264	// the hook firing isn't the same agent that owns the session. After the state
265	// file is written, the hint is unused but remains until ClearSessionState
266	// removes it alongside the state file.
267	//
268	// Returns (created=true) when this call wrote the hint, (created=false) when
269	// the hint already existed (no-op) or agentType was empty/Unknown.
270	//
271	// Banner display is gated separately via ClaimSessionStartBanner — winning
272	// the ownership claim does NOT mean this agent should also print the banner,
273	// because the winner may not implement HookResponseWriter (e.g., Cursor).
274	func StoreAgentTypeHint(ctx context.Context, sessionID string, agentType types.AgentType) (created bool, err error) {
275		if vErr := validation.ValidateSessionID(sessionID); vErr != nil {
276			return false, fmt.Errorf("invalid session ID: %w", vErr)
277		}
278		if agentType == "" || agentType == agent.AgentTypeUnknown {
279			return false, nil
280		}
281	
282		stateDir, sErr := getSessionStateDir(ctx)
283		if sErr != nil {
284			return false, fmt.Errorf("failed to get session state directory: %w", sErr)
285		}
286		if mErr := os.MkdirAll(stateDir, 0o750); mErr != nil {
287			return false, fmt.Errorf("failed to create session state directory: %w", mErr)
288		}
289	
290		hintFile := filepath.Join(stateDir, sessionID+".agent")
291		f, oErr := os.OpenFile(hintFile, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0o600) //nolint:gosec // hintFile path is built from validated sessionID
292		if oErr != nil {
293			if errors.Is(oErr, os.ErrExist) {
294				// First-writer-wins: another caller already claimed this session.
295				return false, nil
296			}
297			return false, fmt.Errorf("failed to create agent hint file: %w", oErr)
298		}
299		defer f.Close()
300		if _, wErr := f.WriteString(string(agentType)); wErr != nil {
301			return false, fmt.Errorf("failed to write agent hint file: %w", wErr)
302		}
303		return true, nil
304	}
